<script setup>
import { ref,onBeforeUnmount } from 'vue'
import { encodeWav } from './wav.js'
const emit=defineEmits(['file','fallback','close'])
const recording=ref(false),url=ref(''),file=ref(null),message=ref(''),seconds=ref(0)
let recorder,stream,timer,permissionTimer,context,source,processor,gain,generation=0,pcm=[],sampleCount=0
function release(){clearTimeout(permissionTimer);clearInterval(timer);stream?.getTracks().forEach(t=>t.stop());if(processor){processor.onaudioprocess=null;processor.disconnect()}source?.disconnect();gain?.disconnect();context?.close().catch(()=>{});processor=source=gain=context=null}
function cleanup(){++generation;release();if(recorder?.state==='recording')recorder.stop();recording.value=false;if(url.value)URL.revokeObjectURL(url.value);url.value='';file.value=null;pcm=[];sampleCount=0}
function finish(blob,token){if(token!==generation)return;recording.value=false;file.value=new File([blob],`现场录音-${Date.now()}.wav`,{type:'audio/wav'});url.value=URL.createObjectURL(file.value)}
async function start(){cleanup();message.value='';const token=generation;const mime=['audio/wav','audio/x-wav'].find(x=>globalThis.MediaRecorder?.isTypeSupported(x));const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!globalThis.isSecureContext || !navigator.mediaDevices?.getUserMedia || (!mime && !Audio)){message.value='此浏览器无法录音。请选择 WAV 或 MP3 音频文件；不会自动转写。';return}try{permissionTimer=setTimeout(()=>{if(token===generation){cleanup();message.value='麦克风授权等待超时，请重试或选择音频文件。'}},30000);const acquired=await navigator.mediaDevices.getUserMedia({audio:true});if(token!==generation){acquired.getTracks().forEach(t=>t.stop());return}clearTimeout(permissionTimer);stream=acquired;
if(mime){const chunks=[];let size=0;recorder=new MediaRecorder(stream,{mimeType:mime});recorder.ondataavailable=e=>{if(token!==generation)return;size+=e.data.size;if(size>20*1024*1024){cleanup();message.value='录音超过20MB，已取消。';return}chunks.push(e.data)};recorder.onstop=()=>{if(token!==generation)return;release();finish(new Blob(chunks,{type:'audio/wav'}),token)};recorder.onerror=()=>{if(token!==generation)return;cleanup();message.value='录音失败，请选择音频文件。'};recorder.start(1000)}else{context=new Audio();await context.resume();if(token!==generation)return;source=context.createMediaStreamSource(stream);processor=context.createScriptProcessor(4096,1,1);gain=context.createGain();gain.gain.value=0;processor.onaudioprocess=event=>{if(token!==generation)return;const chunk=new Float32Array(event.inputBuffer.getChannelData(0));pcm.push(chunk);sampleCount+=chunk.length;if(sampleCount*2+44>=20*1024*1024)stop()};source.connect(processor);processor.connect(gain);gain.connect(context.destination)}
seconds.value=0;recording.value=true;timer=setInterval(()=>{seconds.value++;if(seconds.value>=120)stop()},1000)}catch(e){if(token!==generation)return;cleanup();message.value='无法使用麦克风，请检查授权或选择音频文件。'}}
function stop(){if(!recording.value)return;clearInterval(timer);if(recorder?.state==='recording'){recorder.stop();stream?.getTracks().forEach(t=>t.stop())}else if(context){const rate=context.sampleRate;const token=generation;const blob=encodeWav(pcm,rate);release();pcm=[];finish(blob,token)}recording.value=false}
function upload(){if(file.value)emit('file',file.value);cleanup();emit('close')}
onBeforeUnmount(cleanup)
</script>
<template><section class="voice-recorder" aria-label="现场录音"><header><button aria-label="返回对话" @click="cleanup();emit('close')">‹</button><h2>说给澍雨听</h2></header><img class="voice-mascot" src="/brand/shuyu-raindrop-v1.png" alt="澍雨助手"><div class="voice-state" role="status">{{ recording ? `正在录音 · ${seconds} 秒` : file ? '录音已就绪，请先回听核对' : '说说现场的情况' }}</div><p>先录音和核对，再上传。转写需要另行点击，整段录音将发送给配置的模型服务。</p><p v-if="message" role="status">{{ message }}</p><button class="voice-primary" v-if="!recording && !file" @click="start">🎙 开始录音</button><button class="voice-primary" v-if="recording" @click="stop">停止录音 · {{ seconds }}秒</button><template v-if="file"><audio :src="url" controls/><p>{{ seconds }}秒 · {{ (file.size/1024).toFixed(1) }} KB</p><button class="voice-primary" @click="upload">确认并上传录音</button><button @click="start">重新录音</button></template><button @click="emit('fallback');emit('close')">选择音频文件</button><button @click="cleanup();emit('close')">取消</button></section></template>

<style scoped>
.voice-recorder{box-sizing:border-box;color:#103d33;background:#fff;padding:22px;max-width:480px;width:100%;border-radius:22px}.voice-recorder header{display:flex;align-items:center;gap:25px}.voice-recorder h2{font-size:23px}.voice-mascot{display:block;width:160px;height:180px;object-fit:contain;margin:22px auto}.voice-state{text-align:center;padding:18px;background:#f1faf1;border-radius:16px;font-size:17px}.voice-recorder p{font-size:14px;line-height:1.7;color:#60776e}.voice-recorder button{min-height:50px;border:1px solid #d7e3dc;border-radius:12px;background:white;color:#165442;font:inherit;font-size:17px;padding:10px 16px;margin:6px 0;width:100%}.voice-recorder header button{width:44px;border:0;font-size:30px}.voice-recorder audio{width:100%;margin:20px 0}.voice-recorder button.voice-primary{background:#165442;color:white}@media(max-width:767px){.voice-recorder{min-height:100%;max-width:none;border-radius:0;padding:18px}.voice-mascot{margin:30px auto}}
</style>